{
  "corrected": "Ayer fui al mercado y compré dos manzanas. El agua está fría.",
  "mistakes": [
    {
      "wrong": "yo voy",
      "right": "fui",
      "explanation": "You are talking about something that happened yesterday (a past action), so you need the past tense (pretérito) of 'ir' (to go), which is 'fui'."
    },
    {
      "wrong": "dos manzana",
      "right": "dos manzanas",
      "explanation": "The word 'manzana' (apple) is feminine, so it needs to be plural ('manzanas') because you bought two."
    },
    {
      "wrong": "La agua",
      "right": "El agua",
      "explanation": "The word 'agua' (water) is feminine, but it is used as an uncountable noun, so it uses the masculine article 'el' when referring to water in general."
    }
  ]
}

{
  "corrected": "Hier, je suis allé au marché et j'ai acheté deux pommes. J'ai 25 ans et la maison est grande.",
  "mistakes": [
    {
      "wrong": "pomme",
      "right": "pommes",
      "explanation": "When you say 'two apples', you need the plural form: 'pommes'."
    },
    {
      "wrong": "le maison",
      "right": "la maison",
      "explanation": "The word 'maison' is feminine, so you must use the feminine article 'la', not 'le'."
    },
    {
      "wrong": "grand",
      "right": "grande",
      "explanation": "Since 'maison' is feminine, the adjective describing it must also be feminine: 'grande'."
    }
  ]
}

{
  "corrected": "कल मैं बाज़ार गया था और दो सेब खरीदे। मेरे भाई डॉक्टर हैं।",
  "mistakes": [
    {
      "wrong": "जाता हूँ",
      "right": "गया था",
      "explanation": "Since the action happened in the past ('कल' - yesterday), you should use the past tense (gaya tha) instead of the present tense (jaata hoon)."
    },
    {
      "wrong": "खरीदा",
      "right": "खरीदे",
      "explanation": "The verb 'खरीदना' (to buy) needs to agree with the plural object ('दो सेब' - two apples). The correct past tense form for plural objects is 'खरीदे'."
    },
    {
      "wrong": "मेरी भाई",
      "right": "मेरे भाई",
      "explanation": "The possessive pronoun for 'my' before a masculine noun like 'भाई' (brother) should be 'मेरे' (mere), not 'मेरी' (meri)."
    },
    {
      "wrong": "डॉक्टर है",
      "right": "डॉक्टर हैं",
      "explanation": "Since 'भाई' (brother) is plural (even if it's just one brother, the context implies a general statement, and 'भाई' is treated as plural in this context when referring to a profession), the verb should be plural: 'हैं' (hain)."
    }
  ]
}

{
  "corrected": "昨日、私は店に行きました。りんごを二つ買いました。私の兄は医者です。",
  "mistakes": [
    {
      "wrong": "行きます",
      "right": "行きました",
      "explanation": "The verb '行く' (to go) in the past tense is '行きました'."
    },
    {
      "wrong": "買いました",
      "right": "買いました",
      "explanation": "This is correct, but often '買った' (past tense of 買う) is used for simple actions like buying things. Both are acceptable, but '買いました' is fine."
    },
    {
      "wrong": "医者がです",
      "right": "医者です",
      "explanation": "The particle 'が' (ga) is used for subjects, but here you are stating a fact about your brother, so you just need the noun followed by the copula 'です'."
    }
  ]
}
